parameters.jsCode:
const results = [];

for (const item of $input.all()) {
  let raw = item.json.output ?? '';
  let parsed = {};
  let parseError = false;

  try {
    // Strip code fences in case the model adds them despite instructions
    const cleaned = String(raw)
      .replace(/```json|```/gi, '')
      .trim();

    // Fall back to the first {...} block if extra text surrounds the JSON
    const match = cleaned.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(match ? match[0] : cleaned);
  } catch (e) {
    parseError = true;
  }

  let url = (parsed.faculty_directory_url || '').trim();

  // Only accept absolute http(s) URLs
  if (!/^https?:\/\/\S+$/i.test(url)) {
    url = '';
  }

  results.push({
    json: {
      university: parsed.university || '',
      department: parsed.department || '',
      faculty_directory_url: url,
      has_url: url !== '',
      source: parsed.source || 'none',
      confidence: parsed.confidence || 'low',
      reason: parsed.reason || '',
      parse_error: parseError
    }
  });
}

return results;

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const cleanRole = (v) => clean(v).replace(/[;,\s]+$/, ''); // strips stray trailing ";" or ","

const rows = [];
const seen = new Set();

for (const item of $input.all()) {
  const faculty = item.json?.data?.faculty ?? item.json?.faculty ?? [];

  for (const p of faculty) {
    const name = clean(p.name);
    if (!name) continue;

    // De-duplicate by email, falling back to name
    const key = (clean(p.email) || name).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    rows.push({
      json: {
        'Name': name,
        'Role': cleanRole(p.role),
        'Dept': clean(p.department),
        'Email': clean(p.email).toLowerCase(),
        'Uni Webpage': clean(p.university_webpage),
        'Personal Website': clean(p.personal_website),
        'Research Fields': clean(p.research_fields)
      }
    });
  }
}

return rows;

